/* Embedded logo images — always available on Netlify */
const BD_IMAGES = {
  'fortnite': 'data:image/png;base64,',
  'valorant': 'data:image/png;base64,',
  'gta5': 'data:image/png;base64,',
  'warzone': 'data:image/png;base64,',
  'apex': 'data:image/png;base64,',
  'cs2': 'data:image/png;base64,',
  'minecraft': 'data:image/png;base64,',
  'roblox': 'data:image/png;base64,',
  'rocketleague': 'data:image/png;base64,',
  'league': 'data:image/png;base64,',
  'overwatch': 'data:image/png;base64,',
  'fc25': 'data:image/png;base64,',
  'windows': 'data:image/png;base64,',
  'xbox': 'data:image/png;base64,',
  'playstation': 'data:image/png;base64,',
  'nintendo': 'data:image/png;base64,',
  'nintendo-svg': 'data:image/svg+xml;base64,',
};
function bdApplyImages() {
  document.querySelectorAll("img[data-bd-img]").forEach(img => {
    const src = BD_IMAGES[img.dataset.bdImg];
    if (src) img.src = src;
  });
}
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", bdApplyImages);
else bdApplyImages();
